}

export interface Candle {
  time: number;
  open: number;
  high: number;
  low: number;
  close: number;
  volume: number;
}

export interface Trade {
  entry_time: string;
  entry_price: number;
  exit_time: string;
  exit_price: number;
  profit: string;
  risk_percentage: string;
  isLong: boolean;
  session: string;
  volatility: string;
  stoploss: number;
  rsi: number;
  atr: number;
}

export interface Analysis {
  startTime: string;
  endTime: string;
  totalDays: number;
  totalTrades: number;
  winRate: string;
  totalProfit: string;
  profitFactor: string;
  maxDrawdown: string;
  avgProfit: string;
  sharpeRatio: string;
  cumulativeProfit: string[];
  bestTrade: Trade;
  worstTrade: Trade;
