import React from 'react';

interface StatCardProps {
  label: string;
  value: string | number;
  subValue?: string;
  trend?: 'up' | 'down' | 'neutral';
  prefix?: string;
  suffix?: string;
}

const StatCard: React.FC<StatCardProps> = ({ label, value, subValue, trend, prefix, suffix }) => {
  const getTrendColor = () => {
    if (trend === 'up') return 'text-emerald-400';
    if (trend === 'down') return 'text-rose-400';
    return 'text-slate-400';
  };

  return (
    <div className="bg-slate-800/50 border border-slate-700 p-4 rounded-xl shadow-sm hover:shadow-md transition-shadow">
      <p className="text-sm font-medium text-slate-400 mb-1">{label}</p>
      <div className="flex items-baseline gap-1">
        <span className={`text-2xl font-bold ${getTrendColor()}`}>
          {prefix}{value}{suffix}
        </span>
        {subValue && (
          <span className="text-xs text-slate-500 font-medium">{subValue}</span>
        )}
      </div>
    </div>
  );
};

export default StatCard;

import React, { useEffect, useRef } from 'react';
import * as d3 from 'd3';
import { Candle } from '../types';

interface CandleChartProps {
  data: Candle[];
}

const CandleChart: React.FC<CandleChartProps> = ({ data }) => {
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!containerRef.current || !data.length) return;

    // Clear previous
    d3.select(containerRef.current).selectAll('*').remove();

    const margin = { top: 20, right: 60, bottom: 30, left: 40 };
    const width = containerRef.current.clientWidth - margin.left - margin.right;
    const height = 400 - margin.top - margin.bottom;

    const svg = d3.select(containerRef.current)
      .append('svg')
      .attr('width', width + margin.left + margin.right)
      .attr('height', height + margin.top + margin.bottom)
      .append('g')
      .attr('transform', `translate(${margin.left},${margin.top})`);

    // X axis (Time)
    const x = d3.scaleBand()
      .domain(data.map(d => d.time.toString()))
      .range([0, width])
      .padding(0.2);

    // Y axis (Price)
    const yMin = d3.min(data, d => d.low) || 0;
    const yMax = d3.max(data, d => d.high) || 0;
    const yPadding = (yMax - yMin) * 0.1;

    const y = d3.scaleLinear()
      .domain([yMin - yPadding, yMax + yPadding])
      .range([height, 0]);

    // Grid lines
    svg.append('g')
      .attr('class', 'grid')
      .attr('stroke', '#1e293b')
      .attr('stroke-opacity', 0.5)
      .call(d3.axisLeft(y).tickSize(-width).tickFormat(() => ''));

    // Candles
    const candles = svg.selectAll('.candle')
      .data(data)
      .enter()
      .append('g')
      .attr('class', 'candle');

    // Wicks
    candles.append('line')
      .attr('x1', d => (x(d.time.toString()) || 0) + x.bandwidth() / 2)
      .attr('x2', d => (x(d.time.toString()) || 0) + x.bandwidth() / 2)
      .attr('y1', d => y(d.high))
      .attr('y2', d => y(d.low))
      .attr('stroke', d => d.close >= d.open ? '#10b981' : '#f43f5e')
      .attr('stroke-width', 1);

    // Bodies
    candles.append('rect')
      .attr('x', d => x(d.time.toString()) || 0)
      .attr('y', d => y(Math.max(d.open, d.close)))
      .attr('width', x.bandwidth())
      .attr('height', d => Math.abs(y(d.open) - y(d.close)) || 1)
      .attr('fill', d => d.close >= d.open ? '#10b981' : '#f43f5e');

    // Axes
    svg.append('g')
      .attr('transform', `translate(0,${height})`)
      .attr('color', '#64748b')
      .call(d3.axisBottom(x).tickValues(x.domain().filter((d, i) => !(i % Math.ceil(data.length / 10)))).tickFormat(d => {
        const date = new Date(parseInt(d) * 1000);
        return `${date.getHours()}:${date.getMinutes()}`;
      }));

    svg.append('g')
      .attr('transform', `translate(${width}, 0)`)
      .attr('color', '#64748b')
      .call(d3.axisRight(y).ticks(8));

  }, [data]);

  return (
    <div className="bg-slate-800/50 border border-slate-700 rounded-xl p-4 overflow-hidden">
      <h3 className="text-sm font-semibold text-slate-400 mb-4 uppercase tracking-wider">Price Action (Backtest Window)</h3>
      <div ref={containerRef} className="w-full" style={{ minHeight: '400px' }}></div>
    </div>
  );
};

export default CandleChart;

import React from 'react';
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  AreaChart,
  Area
} from 'recharts';

interface ProfitChartProps {
  data: string[];
}

const ProfitChart: React.FC<ProfitChartProps> = ({ data }) => {
  const chartData = data.map((val, idx) => ({
    trade: idx + 1,
    profit: parseFloat(val)
  }));

  return (
    <div className="bg-slate-800/50 border border-slate-700 rounded-xl p-4 h-[400px]">
      <h3 className="text-sm font-semibold text-slate-400 mb-4 uppercase tracking-wider">Equity Curve</h3>
      <ResponsiveContainer width="100%" height="90%">
        <AreaChart data={chartData}>
          <defs>
            <linearGradient id="colorProfit" x1="0" y1="0" x2="0" y2="1">
              <stop offset="5%" stopColor="#10b981" stopOpacity={0.3}/>
              <stop offset="95%" stopColor="#10b981" stopOpacity={0}/>
            </linearGradient>
          </defs>
          <CartesianGrid strokeDasharray="3 3" stroke="#334155" />
          <XAxis dataKey="trade" stroke="#64748b" fontSize={12} />
          <YAxis stroke="#64748b" fontSize={12} tickFormatter={(val) => `${val}%`} />
          <Tooltip 
            contentStyle={{ backgroundColor: '#1e293b', border: '1px solid #334155', borderRadius: '8px' }}
            labelStyle={{ color: '#94a3b8' }}
          />
          <Area 
            type="monotone" 
            dataKey="profit" 
            stroke="#10b981" 
            fillOpacity={1} 
            fill="url(#colorProfit)" 
            strokeWidth={2}
          />
        </AreaChart>
      </ResponsiveContainer>
    </div>
  );
};

export default ProfitChart;

import { GoogleGenAI } from "@google/genai";
import { Analysis, Trade } from "../types";

export const getStrategyAnalysis = async (analysis: Analysis, trades: Trade[]) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

  const prompt = `
    Act as a professional algorithmic trading analyst. 
    Analyze the following backtest results for a BTC strategy and provide a concise, high-impact summary.

    Stats:
    - Win Rate: ${analysis.winRate}%
    - Total Profit: ${analysis.totalProfit}%
    - Profit Factor: ${analysis.profitFactor}
    - Max Drawdown: ${analysis.maxDrawdown}%
    - Sharpe Ratio: ${analysis.sharpeRatio}
    - Total Trades: ${analysis.totalTrades}

    Session Performance:
    ${JSON.stringify(analysis.sessionProfit)}

    Best Trade Profit: ${analysis.bestTrade.profit}%
    Worst Trade Profit: ${analysis.worstTrade.profit}%

    Questions to answer:
    1. Is this strategy robust?
    2. What are the key risks based on drawdown and profit factor?
    3. Which trading session seems most optimal?
    4. One specific recommendation to improve the strategy.

    Format the response in clean markdown with headers.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text;
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    return "Failed to generate AI insights. Check your API configuration.";
  }
};

import React, { useState, useEffect, useMemo } from 'react';
import { 
  BarChart3, 
  TrendingUp, 
  Activity, 
  Clock, 
  Calendar, 
  Target, 
  ArrowUpRight, 
  ArrowDownRight,
  RefreshCcw,
  LayoutDashboard,
  BrainCircuit,
  AlertCircle
} from 'lucide-react';
import { BacktestResponse, BacktestParams } from './types';
import { SYMBOL_OPTIONS, INTERVAL_OPTIONS, MOCK_RESPONSE } from './constants';
import StatCard from './components/StatCard';
import CandleChart from './components/CandleChart';
import ProfitChart from './components/ProfitChart';
import { getStrategyAnalysis } from './services/geminiService';

const App: React.FC = () => {
  const [params, setParams] = useState<BacktestParams>({
    symbol: 'BTCUSD',
    interval: '15m',
    start: Math.floor(Date.now() / 1000) - (86400 * 7), // Last 7 days
    end: Math.floor(Date.now() / 1000)
  });

  const [loading, setLoading] = useState(false);
  const [data, setData] = useState<BacktestResponse | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [aiInsight, setAiInsight] = useState<string | null>(null);
  const [aiLoading, setAiLoading] = useState(false);

  const handleRunBacktest = async () => {
    setLoading(true);
    setError(null);
    setAiInsight(null);

    try {
      const url = `http://localhost:4040/api/analyze?symbol=${params.symbol}&interval=${params.interval}&onlytrade=true&start=${params.start}&end=${params.end}`;
      const response = await fetch(url);

      if (!response.ok) {
        throw new Error(`API Error: ${response.statusText}. Using mock data for preview.`);
      }

      const result = await response.json();
      setData(result);
    } catch (err: any) {
      console.warn("Falling back to mock data as local API is unreachable:", err.message);
      // In a real app, you might show the error. Here we use user's mock response as demo data
      setData(MOCK_RESPONSE);
      setError("Note: Local API at localhost:4040 not found. Displaying mock data for demonstration.");
    } finally {
      setLoading(false);
    }
  };

  const getAIInsights = async () => {
    if (!data) return;
    setAiLoading(true);
    const insight = await getStrategyAnalysis(data.analysis, data.trades);
    setAiInsight(insight || "No insight generated.");
    setAiLoading(false);
  };

  // Run initial backtest
  useEffect(() => {
    handleRunBacktest();
  }, []);

  const stats = useMemo(() => {
    if (!data) return null;
    return data.analysis;
  }, [data]);

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 flex flex-col">
      {/* Top Navbar */}
      <header className="sticky top-0 z-50 bg-slate-900/80 backdrop-blur-md border-b border-slate-800 px-6 py-4 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="bg-emerald-500/10 p-2 rounded-lg">
            <TrendingUp className="text-emerald-500 w-6 h-6" />
          </div>
          <h1 className="text-xl font-bold tracking-tight">Strategy<span className="text-emerald-500">Backtester</span></h1>
        </div>

        <div className="flex items-center gap-4 bg-slate-800/50 p-1.5 rounded-xl border border-slate-700">
          <select 
            value={params.symbol}
            onChange={(e) => setParams(prev => ({ ...prev, symbol: e.target.value }))}
            className="bg-transparent border-none text-sm font-medium focus:ring-0 px-3 py-1.5 rounded-lg hover:bg-slate-700 transition-colors"
          >
            {SYMBOL_OPTIONS.map(opt => <option key={opt} value={opt} className="bg-slate-900">{opt}</option>)}
          </select>
          <div className="w-px h-6 bg-slate-700"></div>
          <select 
            value={params.interval}
            onChange={(e) => setParams(prev => ({ ...prev, interval: e.target.value }))}
            className="bg-transparent border-none text-sm font-medium focus:ring-0 px-3 py-1.5 rounded-lg hover:bg-slate-700 transition-colors"
          >
            {INTERVAL_OPTIONS.map(opt => <option key={opt} value={opt} className="bg-slate-900">{opt}</option>)}
          </select>
          <div className="w-px h-6 bg-slate-700"></div>
          <button 
            onClick={handleRunBacktest}
            disabled={loading}
            className={`flex items-center gap-2 px-6 py-2 rounded-lg text-sm font-bold transition-all ${loading ? 'bg-slate-700 text-slate-400' : 'bg-emerald-500 hover:bg-emerald-600 text-white shadow-lg shadow-emerald-500/20 active:scale-95'}`}
          >
            {loading ? <RefreshCcw className="w-4 h-4 animate-spin" /> : <PlayIcon />}
            {loading ? 'Running...' : 'Run Backtest'}
          </button>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 p-6 max-w-7xl mx-auto w-full space-y-6">
        {error && (
          <div className="bg-amber-500/10 border border-amber-500/20 text-amber-400 px-4 py-3 rounded-xl flex items-center gap-3">
            <AlertCircle className="w-5 h-5 flex-shrink-0" />
            <span className="text-sm font-medium">{error}</span>
          </div>
        )}

        {!data ? (
          <div className="h-[60vh] flex flex-col items-center justify-center space-y-4 text-slate-500">
            <RefreshCcw className="w-12 h-12 animate-spin text-emerald-500" />
            <p className="text-lg font-medium">Analyzing historical data...</p>
          </div>
        ) : (
          <>
            {/* Quick Stats Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
              <StatCard 
                label="Win Rate" 
                value={stats?.winRate || 0} 
                suffix="%" 
                trend={parseFloat(stats?.winRate || '0') > 50 ? 'up' : 'down'}
              />
              <StatCard 
                label="Total Profit" 
                value={stats?.totalProfit || 0} 
                suffix="%" 
                trend={parseFloat(stats?.totalProfit || '0') > 0 ? 'up' : 'down'}
              />
              <StatCard 
                label="Profit Factor" 
                value={stats?.profitFactor || 0} 
                trend={parseFloat(stats?.profitFactor || '0') > 1.5 ? 'up' : 'neutral'}
              />
              <StatCard 
                label="Sharpe Ratio" 
                value={stats?.sharpeRatio || 0} 
                trend={parseFloat(stats?.sharpeRatio || '0') > 1 ? 'up' : 'neutral'}
              />
            </div>

            {/* Main Charts Section */}
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
              <div className="lg:col-span-2">
                <ProfitChart data={stats?.cumulativeProfit || []} />
              </div>
              <div className="space-y-6">
                <div className="bg-slate-800/50 border border-slate-700 rounded-xl p-5">
                  <div className="flex items-center justify-between mb-4">
                    <h3 className="text-sm font-semibold text-slate-400 uppercase tracking-wider flex items-center gap-2">
                      <Target className="w-4 h-4" /> Performance Highlights
                    </h3>
                  </div>
                  <div className="space-y-4">
                    <div className="flex items-center justify-between">
                      <span className="text-sm text-slate-400">Total Trades</span>
                      <span className="font-bold">{stats?.totalTrades}</span>
                    </div>
                    <div className="flex items-center justify-between">
                      <span className="text-sm text-slate-400">Max Drawdown</span>
                      <span className="font-bold text-rose-400">{stats?.maxDrawdown}%</span>
                    </div>
                    <div className="flex items-center justify-between">
                      <span className="text-sm text-slate-400">Avg Profit</span>
                      <span className="font-bold text-emerald-400">{stats?.avgProfit}%</span>
                    </div>
                  </div>
                </div>

                <div className="bg-slate-800/50 border border-slate-700 rounded-xl p-5">
                  <div className="flex items-center justify-between mb-4">
                    <h3 className="text-sm font-semibold text-slate-400 uppercase tracking-wider flex items-center gap-2">
                      <Clock className="w-4 h-4" /> Session Profit
                    </h3>
                  </div>
                  <div className="space-y-3">
                    {Object.entries(stats?.sessionProfit || {}).map(([session, profit]) => (
                      <div key={session} className="flex items-center justify-between">
                        <span className="text-sm text-slate-400 truncate mr-2">{session}</span>
                        <span className={`font-bold ${profit >= 0 ? 'text-emerald-400' : 'text-rose-400'}`}>
                          {profit > 0 ? '+' : ''}{profit}%
                        </span>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            </div>

            {/* Price Chart */}
            {data.candles && data.candles.length > 0 && (
              <CandleChart data={data.candles.slice(-100)} />
