import React, { useEffect, useRef } from 'react';
import { createChart, IChartApi, ColorType, LineStyle } from 'lightweight-charts';
import { Candle, Trade } from '../types';

interface TradingChartProps {
  candles: Candle[];
  trades: Trade[];
  focusedTradeId?: number;
}

const TradingChart: React.FC<TradingChartProps> = ({ candles, trades, focusedTradeId }) => {
  const chartContainerRef = useRef<HTMLDivElement>(null);
  const chartRef = useRef<IChartApi | null>(null);

  // Helper to parse the custom date format from the API
  const parseTime = (dateStr: string) => {
    // Expected format: "18/07/2025, 18:30:00"
    const [datePart, timePart] = dateStr.split(', ');
    const [day, month, year] = datePart.split('/').map(Number);
    const [hour, min, sec] = timePart.split(':').map(Number);
    return new Date(year, month - 1, day, hour, min, sec).getTime() / 1000;
  };

  useEffect(() => {
    if (!chartContainerRef.current || !candles.length) return;

    const chart = createChart(chartContainerRef.current, {
      layout: {
        background: { type: ColorType.Solid, color: 'transparent' },
        textColor: '#94a3b8',
      },
      grid: {
        vertLines: { color: '#1e293b' },
        horzLines: { color: '#1e293b' },
      },
      width: chartContainerRef.current.clientWidth,
      height: 600,
      timeScale: {
        borderColor: '#334155',
        timeVisible: true,
        secondsVisible: false,
      },
      rightPriceScale: {
        borderColor: '#334155',
      },
    });

    chartRef.current = chart;

    const candleSeries = chart.addCandlestickSeries({
      upColor: '#10b981',
      downColor: '#f43f5e',
      borderVisible: false,
      wickUpColor: '#10b981',
      wickDownColor: '#f43f5e',
    });

    // Format data for lightweight-charts
    const formattedCandles = candles.map(c => ({
      time: c.time as any,
      open: c.open,
      high: c.high,
      low: c.low,
      close: c.close,
    }));

    candleSeries.setData(formattedCandles);

    // Markers for trades
    const markers: any[] = [];
    trades.forEach((trade, index) => {
      const entryTime = parseTime(trade.entry_time);
      const exitTime = parseTime(trade.exit_time);

      markers.push({
        time: entryTime,
        position: trade.isLong ? 'belowBar' : 'aboveBar',
        color: trade.isLong ? '#10b981' : '#f43f5e',
        shape: trade.isLong ? 'arrowUp' : 'arrowDown',
        text: trade.isLong ? 'Buy' : 'Sell',
      });

      markers.push({
        time: exitTime,
        position: trade.isLong ? 'aboveBar' : 'belowBar',
        color: '#64748b',
        shape: 'circle',
        text: 'Exit',
      });

      // Price lines for Stop Loss if focused or all? 
      // For now, let's just show markers. Lightweight Charts supports PriceLines per series.
    });

    candleSeries.setMarkers(markers);

    const handleResize = () => {
      if (chartContainerRef.current) {
        chart.applyOptions({ width: chartContainerRef.current.clientWidth });
      }
    };

    window.addEventListener('resize', handleResize);

    return () => {
      window.removeEventListener('resize', handleResize);
      chart.remove();
    };
  }, [candles, trades]);

  useEffect(() => {
    // Handle scrolling to specific trade
    if (chartRef.current && focusedTradeId !== undefined && trades[focusedTradeId]) {
      const trade = trades[focusedTradeId];
      const entryTime = parseTime(trade.entry_time);

      chartRef.current.timeScale().scrollToPosition(0, true);
      // More accurate zoom:
      chartRef.current.timeScale().setVisibleRange({
        from: (entryTime - 3600 * 4) as any, // 4 hours before
        to: (entryTime + 3600 * 12) as any,  // 12 hours after
      });
    }
  }, [focusedTradeId, trades]);

  return (
    <div className="w-full bg-slate-900 border border-slate-800 rounded-xl p-2 relative">
      <div ref={chartContainerRef} className="w-full h-[600px]" />
      <div className="absolute top-4 left-6 pointer-events-none">
        <h3 className="text-xs font-bold text-slate-500 uppercase tracking-widest bg-slate-900/80 px-2 py-1 rounded">Interactive Trading View</h3>
      </div>
    </div>
  );
};

export default TradingChart;

