import React, { useEffect, useRef } from 'react';
import { createChart, IChartApi, ColorType, LineStyle, ISeriesApi, "Candlestick" } from 'lightweight-charts';
import { Candle, Trade } from '../types';

interface TradingChartProps {
  candles: Candle[];
  trades: Trade[];
  focusedTradeId?: number;
}

const TradingChart: React.FC<TradingChartProps> = ({ candles, trades, focusedTradeId }) => {
  const chartContainerRef = useRef<HTMLDivElement>(null);
  const chartRef = useRef<IChartApi | null>(null);
  const candleSeriesRef = useRef<ISeriesApi<"Candlestick"> | null>(null);
  const slLineRef = useRef<any>(null);
  const entryLineRef = useRef<any>(null);
  const exitLineRef = useRef<any>(null);

  const parseTime = (dateStr: string) => {
    const [datePart, timePart] = dateStr.split(', ');
    const [day, month, year] = datePart.split('/').map(Number);
    const [hour, min, sec] = timePart.split(':').map(Number);
    return new Date(year, month - 1, day, hour, min, sec).getTime() / 1000;
  };

  useEffect(() => {
    if (!chartContainerRef.current || !candles.length) return;

    const chart = createChart(chartContainerRef.current, {
      layout: {
        background: { type: ColorType.Solid, color: '#0f172a' },
        textColor: '#94a3b8',
      },
      grid: {
        vertLines: { color: '#1e293b' },
        horzLines: { color: '#1e293b' },
      },
      width: chartContainerRef.current.clientWidth,
      height: 600,
      timeScale: {
        borderColor: '#334155',
        timeVisible: true,
      },
    });

    chartRef.current = chart;

    const candleSeries = chart.addCandlestickSeries({
      upColor: '#10b981',
      downColor: '#f43f5e',
      borderVisible: false,
      wickUpColor: '#10b981',
      wickDownColor: '#f43f5e',
    });
    candleSeriesRef.current = candleSeries;

    const formattedCandles = candles.map(c => ({
      time: c.time as any,
      open: c.open,
      high: c.high,
      low: c.low,
      close: c.close,
    }));
    candleSeries.setData(formattedCandles);

    const markers: any[] = [];
    trades.forEach((trade) => {
      const isWin = parseFloat(trade.profit) >= 0;
      const entryT = parseTime(trade.entry_time);
      const exitT = parseTime(trade.exit_time);

      markers.push({
        time: entryT,
        position: trade.isLong ? 'belowBar' : 'aboveBar',
        color: trade.isLong ? '#10b981' : '#f43f5e',
        shape: trade.isLong ? 'arrowUp' : 'arrowDown',
        text: `Entry ${trade.isLong ? 'Long' : 'Short'}`,
      });

      markers.push({
        time: exitT,
        position: isWin ? 'aboveBar' : 'belowBar',
        color: isWin ? '#fbbf24' : '#64748b',
        shape: 'circle',
        text: `Exit (${trade.profit}%)`,
      });
    });
    candleSeries.setMarkers(markers);

    const handleResize = () => {
      if (chartContainerRef.current) {
        chart.applyOptions({ width: chartContainerRef.current.clientWidth });
      }
    };
    window.addEventListener('resize', handleResize);

    return () => {
      window.removeEventListener('resize', handleResize);
      chart.remove();
    };
  }, [candles, trades]);

  useEffect(() => {
    if (!chartRef.current || !candleSeriesRef.current) return;

    // Clear old lines
    if (slLineRef.current) candleSeriesRef.current.removePriceLine(slLineRef.current);
    if (entryLineRef.current) candleSeriesRef.current.removePriceLine(entryLineRef.current);
    if (exitLineRef.current) candleSeriesRef.current.removePriceLine(exitLineRef.current);

    if (focusedTradeId !== undefined && trades[focusedTradeId]) {
      const trade = trades[focusedTradeId];
      const entryTime = parseTime(trade.entry_time);

      // Plot SL
      slLineRef.current = candleSeriesRef.current.createPriceLine({
        price: trade.stoploss,
        color: '#f43f5e',
        lineWidth: 2,
        lineStyle: LineStyle.Dashed,
        axisLabelVisible: true,
        title: 'Stop Loss',
      });

      // Plot Entry
      entryLineRef.current = candleSeriesRef.current.createPriceLine({
        price: trade.entry_price,
        color: '#94a3b8',
        lineWidth: 2,
        lineStyle: LineStyle.Solid,
        axisLabelVisible: true,
        title: 'Entry Price',
      });

      // Plot Exit
      exitLineRef.current = candleSeriesRef.current.createPriceLine({
        price: trade.exit_price,
        color: '#fbbf24',
        lineWidth: 2,
        lineStyle: LineStyle.Dotted,
        axisLabelVisible: true,
        title: 'Exit Target',
      });

      chartRef.current.timeScale().setVisibleRange({
        from: (entryTime - 3600 * 2) as any,
        to: (parseTime(trade.exit_time) + 3600 * 4) as any,
      });
    }
  }, [focusedTradeId, trades]);

  return (
    <div className="w-full bg-slate-900 border border-slate-800 rounded-xl p-2 relative shadow-2xl">
      <div ref={chartContainerRef} className="w-full h-[600px]" />
      <div className="absolute top-4 left-6 flex items-center gap-4 bg-slate-900/90 border border-slate-700/50 p-3 rounded-lg backdrop-blur shadow-xl pointer-events-none">
        <div className="flex flex-col">
          <h3 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Backtest Environment</h3>
          <span className="text-xs font-bold text-emerald-500">Live Execution Simulation</span>
        </div>
      </div>
    </div>
  );
};

