import React from 'react';

interface StatCardProps {
  label: string;
  value: string | number;
  subValue?: string;
  trend?: 'up' | 'down' | 'neutral';
  prefix?: string;
  suffix?: string;
  // Added optional labelColor prop to support custom styling for the label text
  labelColor?: string;
}

const StatCard: React.FC<StatCardProps> = ({ label, value, subValue, trend, prefix, suffix, labelColor }) => {
  const getTrendColor = () => {
    if (trend === 'up') return 'text-emerald-400';
    if (trend === 'down') return 'text-rose-400';
    return 'text-slate-400';
  };

  return (
    <div className="bg-slate-800/50 border border-slate-700 p-4 rounded-xl shadow-sm hover:shadow-md transition-shadow">
      {/* Use labelColor prop if provided, otherwise default to text-slate-400 */}
      <p className={`text-sm font-medium mb-1 ${labelColor || 'text-slate-400'}`}>{label}</p>
      <div className="flex items-baseline gap-1">
        <span className={`text-2xl font-bold ${getTrendColor()}`}>
          {prefix}{value}{suffix}
        </span>
        {subValue && (
          <span className="text-xs text-slate-500 font-medium">{subValue}</span>
        )}
      </div>
    </div>
  );
};

export default StatCard;

