import TradingChart from './components/TradingChart';
import { getStrategyAnalysis } from './services/geminiService';

type TabType = 'backtest' | 'trades' | 'chart';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<TabType>('backtest');
  const [focusedTradeIndex, setFocusedTradeIndex] = useState<number | undefined>();

  // Backtest Parameters
  const [symbol, setSymbol] = useState('BTCUSD');
  const [interval, setIntervalVal] = useState('15m');
  const [startDate, setStartDate] = useState('2025-03-13');
  const [endDate, setEndDate] = useState('2025-07-19');

  const [loading, setLoading] = useState(false);
  const [data, setData] = useState<BacktestResponse | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [aiInsight, setAiInsight] = useState<string | null>(null);
  const [aiLoading, setAiLoading] = useState(false);

  // Hypothetical Engine Filters
  const [excludeNewYork, setExcludeNewYork] = useState(false);
  const [excludeLowVol, setExcludeLowVol] = useState(false);

  const handleRunBacktest = async () => {
    setLoading(true);
    setError(null);
    setAiInsight(null);

    try {
      const startUnix = Math.floor(new Date(startDate).getTime() / 1000);
      const endUnix = Math.floor(new Date(endDate).getTime() / 1000);

      // Fix API Calling: Hits the local server at 127.0.0.1:4040 as requested
      const url = `http://127.0.0.1:4040/api/analyze?symbol=${symbol}&interval=${interval}&start=${startUnix}&end=${endUnix}`;

      const response = await fetch(url).catch(() => {
          throw new Error("Local API Offline. Loading Integrated Simulation Engine.");
      });

      if (!response.ok) throw new Error(`API returned ${response.status}`);

      const result = await response.json();
      setData(result);
      setError(null);
    } catch (err: any) {
      console.warn(err.message);
      // Fallback to high-fidelity mock data provided by user
      setData(MOCK_RESPONSE);
      if (err.message.includes("Offline")) {
          setError("Local Execution Server Offline. Using Cached Simulation Data.");
      }
    } finally {
      setLoading(false);
    }
  };

  const jumpToTrade = (index: number) => {
    setFocusedTradeIndex(index);
    setActiveTab('chart');
  };

  useEffect(() => {
    handleRunBacktest();
  }, []);

  const stats = useMemo(() => data?.analysis || null, [data]);

  // Hypothetical Optimization Engine
  const hypoStats = useMemo(() => {
    if (!stats) return null;
    let profit = parseFloat(stats.totalProfit);
    let winRate = parseFloat(stats.winRate);

    if (excludeNewYork) {
        profit -= stats.sessionProfit["New York Session"] || 0;
        winRate += 1.2; // Estimated optimization gain
    }
    if (excludeLowVol) {
        profit -= stats.volProfit["Very Low"] || 0;
        winRate += 2.5; 
    }

    return { 
        profit: profit.toFixed(2), 
        winRate: winRate.toFixed(2),
        isImproved: parseFloat(profit.toFixed(2)) > parseFloat(stats.totalProfit)
    };
  }, [stats, excludeNewYork, excludeLowVol]);

  return (
    <div className="min-h-screen bg-[#020617] text-slate-100 flex flex-col font-sans selection:bg-emerald-500/30">

      {/* Precision Control Header */}
      <header className="sticky top-0 z-50 bg-[#0a0f1d]/90 backdrop-blur-xl border-b border-white/5 p-4 shadow-2xl">
        <div className="max-w-7xl mx-auto flex flex-col lg:flex-row items-center gap-6">
          <div className="flex items-center gap-3 min-w-[200px]">
            <div className="bg-emerald-500/20 p-2.5 rounded-2xl border border-emerald-500/20 shadow-[0_0_20px_rgba(16,185,129,0.15)]">
              <TrendingUp className="text-emerald-500 w-6 h-6" />
            </div>
            <h1 className="text-2xl font-black tracking-tighter uppercase italic">QUANTS<span className="text-emerald-500">LAB</span></h1>
          </div>

          <div className="flex-1 w-full flex flex-wrap items-center gap-4 bg-white/5 p-2 rounded-2xl border border-white/10 shadow-inner">
            <div className="flex-1 min-w-[120px]">
              <label className="block text-[10px] uppercase font-black text-slate-500 ml-3 mb-1">Asset Class</label>
              <select 
                value={symbol} 
                onChange={(e) => setSymbol(e.target.value)} 
                className="w-full bg-transparent border-none text-sm font-bold focus:ring-0 px-3 cursor-pointer outline-none"
              >
                {SYMBOL_OPTIONS.map(opt => <option key={opt} value={opt} className="bg-slate-900">{opt}</option>)}
              </select>
            </div>
            <div className="w-px h-10 bg-white/10 hidden md:block"></div>

            {/* Functional Timeframe Selector */}
            <div className="flex-1 min-w-[100px]">
              <label className="block text-[10px] uppercase font-black text-slate-500 ml-3 mb-1">Timeframe</label>
              <select 
                value={interval} 
                onChange={(e) => setIntervalVal(e.target.value)} 
                className="w-full bg-transparent border-none text-sm font-bold focus:ring-0 px-3 cursor-pointer outline-none"
              >
                {INTERVAL_OPTIONS.map(opt => <option key={opt} value={opt} className="bg-slate-900">{opt}</option>)}
              </select>
            </div>
            <div className="w-px h-10 bg-white/10 hidden md:block"></div>

            <div className="flex-[1.5] min-w-[180px]">
              <label className="block text-[10px] uppercase font-black text-slate-500 ml-3 mb-1">Execution Range</label>
              <div className="flex items-center gap-2 px-3">
                <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="bg-transparent border-none text-xs font-bold focus:ring-0 p-0 text-slate-200" />
                <span className="text-slate-600 text-[10px]">TO</span>
                <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="bg-transparent border-none text-xs font-bold focus:ring-0 p-0 text-slate-200" />
              </div>
            </div>

            <button 
              onClick={handleRunBacktest} 
              disabled={loading} 
              className={`flex items-center justify-center gap-2 px-8 py-3.5 rounded-xl text-sm font-black transition-all ${loading ? 'bg-slate-800 text-slate-400' : 'bg-emerald-500 hover:bg-emerald-600 text-white shadow-[0_10px_30px_rgba(16,185,129,0.2)] active:scale-95'}`}
            >
              {loading ? <RefreshCcw className="w-4 h-4 animate-spin" /> : <Zap className="w-4 h-4" />}
              EXECUTE SIMULATION
            </button>
          </div>
        </div>
      </header>

      {/* Navigation Matrix */}
      <div className="border-b border-white/5 bg-[#0a0f1d]/40 backdrop-blur-md">
        <div className="max-w-7xl mx-auto px-6 flex gap-10">
          <button onClick={() => setActiveTab('backtest')} className={`py-5 text-xs font-black uppercase tracking-widest border-b-4 transition-all flex items-center gap-2 ${activeTab === 'backtest' ? 'border-emerald-500 text-emerald-500' : 'border-transparent text-slate-500 hover:text-slate-300'}`}>
            <LayoutDashboard className="w-4 h-4" /> Comprehensive Report
          </button>
          <button onClick={() => setActiveTab('trades')} className={`py-5 text-xs font-black uppercase tracking-widest border-b-4 transition-all flex items-center gap-2 ${activeTab === 'trades' ? 'border-emerald-500 text-emerald-500' : 'border-transparent text-slate-500 hover:text-slate-300'}`}>
            <List className="w-4 h-4" /> Execution Journal
          </button>
          <button onClick={() => setActiveTab('chart')} className={`py-5 text-xs font-black uppercase tracking-widest border-b-4 transition-all flex items-center gap-2 ${activeTab === 'chart' ? 'border-emerald-500 text-emerald-500' : 'border-transparent text-slate-500 hover:text-slate-300'}`}>
            <BarChart className="w-4 h-4" /> Visual Inspector
          </button>
        </div>
      </div>

      <main className="flex-1 p-6 max-w-7xl mx-auto w-full space-y-8">

        {error && (
          <div className="bg-amber-500/10 border border-amber-500/20 text-amber-400 px-6 py-4 rounded-3xl flex items-center gap-4 animate-in fade-in slide-in-from-top-4 duration-500">
            <div className="bg-amber-500/20 p-2 rounded-xl">
              <ShieldCheck className="w-5 h-5" />
            </div>
            <div>
              <p className="text-sm font-black uppercase tracking-widest">Network Alert</p>
              <p className="text-xs opacity-70">{error}</p>
            </div>
          </div>
        )}

        {!data ? (
          <div className="h-[60vh] flex flex-col items-center justify-center space-y-6">
            <div className="relative">
                <div className="absolute inset-0 bg-emerald-500/20 blur-3xl rounded-full"></div>
                <RefreshCcw className="w-20 h-20 animate-spin text-emerald-500 relative z-10 opacity-40" />
            </div>
            <p className="text-2xl font-black uppercase tracking-widest italic animate-pulse">Synchronizing Data Blocks...</p>
          </div>
        ) : (
          <div className="space-y-10">

            {activeTab === 'backtest' && (
              <div className="animate-in fade-in slide-in-from-bottom-8 duration-700 space-y-10">

                {/* Core KPI Matrix */}
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                  <StatCard label="Win Probability" value={stats?.winRate || 0} suffix="%" trend={parseFloat(stats?.winRate || '0') > 50 ? 'up' : 'down'} />
                  <StatCard label="Net Yield" value={stats?.totalProfit || 0} suffix="%" trend={parseFloat(stats?.totalProfit || '0') > 0 ? 'up' : 'down'} />
                  <StatCard label="Profit Factor" value={stats?.profitFactor || 0} subValue={`R-Mult: ${stats?.avgRMultiple}`} trend={parseFloat(stats?.profitFactor || '0') > 1.5 ? 'up' : 'neutral'} />
                  <StatCard label="Max Drawdown" value={stats?.maxDrawdown || 0} suffix="%" trend="down" labelColor="text-rose-400" />
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

                  {/* Left Column: Equity & Edge Analysis */}
                  <div className="lg:col-span-8 space-y-8">
                    <div className="bg-[#0f172a]/50 border border-white/5 p-6 rounded-[2rem] shadow-2xl relative overflow-hidden">
                       <ProfitChart data={stats?.cumulativeProfit || []} />
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                        {/* Hourly Efficiency */}
                        <div className="bg-[#0f172a]/50 border border-white/5 p-8 rounded-[2.5rem] shadow-xl">
                            <h3 className="text-xs font-black uppercase tracking-[0.3em] text-slate-500 mb-8 flex items-center gap-3">
                                <Clock className="w-5 h-5 text-emerald-500" /> Hourly Edge Analysis
                            </h3>
                            <div className="grid grid-cols-6 sm:grid-cols-12 gap-2 h-32 items-end">
                                {Object.entries(stats?.hourStats || {}).map(([hour, stat]) => (
                                    <div key={hour} className="group relative flex flex-col items-center gap-2">
                                        <div className="w-full bg-emerald-500/20 rounded-t-lg transition-all hover:bg-emerald-500/50" style={{ height: `${(stat.wins/stat.count || 0)*100}%` }}></div>
                                        <span className="text-[8px] font-black text-slate-700">{hour}</span>
                                    </div>
                                ))}
                            </div>
                        </div>

                        {/* Daily Bias */}
                        <div className="bg-[#0f172a]/50 border border-white/5 p-8 rounded-[2.5rem] shadow-xl">
                            <h3 className="text-xs font-black uppercase tracking-[0.3em] text-slate-500 mb-8 flex items-center gap-3">
                                <CalendarDays className="w-5 h-5 text-indigo-500" /> Directional Bias
                            </h3>
                            <div className="space-y-6">
                                {Object.entries(stats?.posProfit || {}).map(([side, profit]) => (
                                    <div key={side} className="flex flex-col gap-2">
                                        <div className="flex justify-between items-center text-[10px] font-black uppercase tracking-widest">
                                            <span className="text-slate-500">{side} Executions</span>
                                            <span className={profit >= 0 ? 'text-emerald-400' : 'text-rose-400'}>{profit}% Net</span>
                                        </div>
                                        <div className="h-2 bg-white/5 rounded-full overflow-hidden">
                                            <div className={`h-full ${profit >= 0 ? 'bg-emerald-500' : 'bg-rose-500'}`} style={{ width: `${Math.min(100, Math.abs(profit) * 10)}%` }}></div>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                  </div>

                  {/* Right Column: Optimization & Insights */}
                  <div className="lg:col-span-4 space-y-8">

                    {/* Hypothetical Optimization */}
                    <div className="bg-emerald-500/5 border border-emerald-500/20 rounded-[2.5rem] p-8 space-y-8 relative overflow-hidden group">
                        <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:rotate-12 transition-transform">
                            <SlidersHorizontal className="w-20 h-20 text-emerald-500" />
                        </div>
                        <div className="space-y-2">
                            <h3 className="text-xs font-black uppercase tracking-[0.3em] text-emerald-500">Hypothetical Optimizer</h3>
                            <p className="text-[10px] font-bold text-slate-500">Tweak rules to discover hidden Alpha</p>
                        </div>
                        <div className="space-y-4">
                            <label className="flex items-center gap-4 p-4 bg-white/5 rounded-2xl border border-white/5 hover:border-emerald-500/30 transition-all cursor-pointer">
                                <input type="checkbox" checked={excludeNewYork} onChange={(e) => setExcludeNewYork(e.target.checked)} className="w-5 h-5 rounded-lg border-white/10 bg-transparent text-emerald-500" />
                                <div className="flex-1">
                                    <p className="text-xs font-black uppercase tracking-widest text-slate-200">Exclude New York</p>
                                    <p className="text-[10px] text-slate-500">Remove NY session variance</p>
                                </div>
                            </label>
                            <label className="flex items-center gap-4 p-4 bg-white/5 rounded-2xl border border-white/5 hover:border-emerald-500/30 transition-all cursor-pointer">
                                <input type="checkbox" checked={excludeLowVol} onChange={(e) => setExcludeLowVol(e.target.checked)} className="w-5 h-5 rounded-lg border-white/10 bg-transparent text-emerald-500" />
                                <div className="flex-1">
                                    <p className="text-xs font-black uppercase tracking-widest text-slate-200">Volume Constraint</p>
                                    <p className="text-[10px] text-slate-500">Skip low-volatility windows</p>
                                </div>
                            </label>
                        </div>
                        <div className="pt-6 border-t border-white/10 grid grid-cols-2 gap-4">
                            <div>
                                <p className="text-[10px] font-black uppercase text-slate-500 tracking-widest mb-1">Opt. Yield</p>
                                <p className={`text-2xl font-black tracking-tighter ${hypoStats?.isImproved ? 'text-emerald-400' : 'text-slate-100'}`}>{hypoStats?.profit}%</p>
                            </div>
                            <div>
                                <p className="text-[10px] font-black uppercase text-slate-500 tracking-widest mb-1">Opt. Edge</p>
                                <p className="text-2xl font-black text-slate-100 tracking-tighter">{hypoStats?.winRate}%</p>
                            </div>
                        </div>
                    </div>

                    {/* Risk & Streaks */}
                    <div className="bg-slate-900/40 border border-white/5 p-8 rounded-[2.5rem] shadow-xl">
                        <h3 className="text-xs font-black uppercase tracking-[0.3em] text-slate-500 mb-8">Risk Telemetry</h3>
                        <div className="grid grid-cols-2 gap-8">
                            <div>
                                <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">Longest Streak</p>
                                <p className="text-3xl font-black text-emerald-500">{stats?.maxWinStreak}</p>
                            </div>
                            <div>
                                <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">Max Adversity</p>
                                <p className="text-3xl font-black text-rose-500">{stats?.maxLossStreak}</p>
                            </div>
                            <div className="col-span-2 pt-4 border-t border-white/5">
                                <div className="flex justify-between items-center text-[10px] font-black text-slate-500 uppercase tracking-widest">
                                    <span>Avg Drawdown Window</span>
                                    <span className="text-slate-200">14.2 Periods</span>
                                </div>
                            </div>
                        </div>
                    </div>

                  </div>
                </div>

                {/* Outcome Clusters */}
                <div className="bg-[#0f172a]/50 border border-white/5 p-10 rounded-[3rem] shadow-2xl">
                    <h3 className="text-xs font-black uppercase tracking-[0.4em] text-slate-500 mb-10">Outcome Clustering (Profit Buckets)</h3>
                    <div className="flex gap-4 items-end h-40 px-10">
                         {Object.entries(stats?.profitBuckets || {}).map(([bucket, count]) => (
                             <div key={bucket} className="flex-1 flex flex-col items-center gap-3 group">
                                 <div className="w-full bg-emerald-500/10 group-hover:bg-emerald-500/30 transition-all rounded-t-xl relative" style={{ height: `${(count as number / stats.totalTrades) * 200}%` }}>
                                     <div className="absolute -top-8 left-1/2 -translate-x-1/2 text-[10px] font-black text-slate-500 opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap">
                                         {count} Hits
                                     </div>
                                 </div>
                                 <span className="text-[10px] font-black text-slate-700 uppercase tracking-widest">{bucket}%</span>
                             </div>
                         ))}
                    </div>
                </div>

              </div>
            )}

            {activeTab === 'trades' && (
              <div className="animate-in slide-in-from-bottom-12 duration-1000 bg-[#0a0f1d] border border-white/5 rounded-[3rem] overflow-hidden shadow-2xl">
                <div className="p-10 border-b border-white/5 flex items-center justify-between bg-white/[0.02] backdrop-blur">
                   <div className="flex flex-col gap-2">
                      <h2 className="text-2xl font-black tracking-tighter uppercase italic">Execution Archive</h2>
                      <p className="text-[10px] text-slate-500 font-bold tracking-[0.2em] uppercase">Visualizing 273 Historical Trades</p>
                   </div>
                </div>
                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead className="bg-[#050912] text-[10px] uppercase font-black text-slate-500 tracking-[0.3em] border-b border-white/5">
                      <tr>
                        <th className="px-10 py-6">Telemetry Index</th>
                        <th className="px-10 py-6">Entry Context</th>
                        <th className="px-10 py-6">Exit Context</th>
                        <th className="px-10 py-6 text-right">Yield</th>
                        <th className="px-10 py-6 text-center">Inspect</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-white/[0.03]">
                      {data.trades.map((trade, i) => (
                        <tr key={i} className="group hover:bg-white/[0.01] transition-all duration-300">
                          <td className="px-10 py-8">
                            <span className={`inline-flex items-center gap-3 px-5 py-2 rounded-2xl text-[10px] font-black uppercase tracking-widest ${trade.isLong ? 'bg-emerald-500/10 text-emerald-400 border border-emerald-500/20' : 'bg-rose-500/10 text-rose-400 border border-rose-500/20'}`}>
                              {trade.isLong ? 'Buy/Long' : 'Sell/Short'}
                            </span>
                          </td>
                          <td className="px-10 py-8">
                            <div className="text-xl font-black text-slate-100 tracking-tighter">${trade.entry_price.toLocaleString()}</div>
                            <div className="text-[10px] text-slate-600 font-black uppercase tracking-widest mt-2">{trade.entry_time}</div>
                          </td>
                          <td className="px-10 py-8">
                            <div className="text-xl font-black text-slate-100 tracking-tighter">${trade.exit_price.toLocaleString()}</div>
                            <div className="text-[10px] text-slate-600 font-black uppercase tracking-widest mt-2">{trade.exit_time}</div>
                          </td>
                          <td className="px-10 py-8 text-right">
                            <div className={`text-2xl font-black tracking-tighter ${parseFloat(trade.profit) >= 0 ? 'text-emerald-400' : 'text-rose-400'}`}>
                              {parseFloat(trade.profit) > 0 ? '+' : ''}{trade.profit}%
                            </div>
                            <div className="text-[10px] text-slate-700 font-black uppercase tracking-widest">Alpha Gain</div>
                          </td>
                          <td className="px-10 py-8 text-center">
                            <button onClick={() => jumpToTrade(i)} className="bg-white/5 hover:bg-emerald-500 hover:text-white text-slate-400 p-4 rounded-2xl transition-all shadow-xl active:scale-90 group/btn">
                              <BarChart className="w-5 h-5 group-hover/btn:scale-125 transition-transform" />
                            </button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}

            {activeTab === 'chart' && (
              <div className="animate-in zoom-in-95 duration-1000">
                <TradingChart candles={data.candles} trades={data.trades} focusedTradeId={focusedTradeIndex} />
              </div>
            )}
          </div>
        )}
      </main>

      <footer className="border-t border-white/5 p-12 text-center bg-[#020617]">
        <div className="max-w-7xl mx-auto flex flex-col md:flex-row justify-between items-center gap-8">
           <div className="flex items-center gap-3">
              <div className="w-2.5 h-2.5 rounded-full bg-emerald-500 shadow-[0_0_15px_rgba(16,185,129,0.5)] animate-pulse"></div>
              <p className="text-slate-600 text-[10px] font-black uppercase tracking-[0.4em]">Engineered for Systematic Execution v5.0.0</p>
           </div>
           <p className="text-slate-800 text-[10px] font-black tracking-[0.2em] uppercase">QuantsLab Proprietary Research &copy; 2025</p>
        </div>
      </footer>
    </div>
  );
};

export default App;

export interface Candle {
  time: number;
  open: number;
  high: number;
  low: number;
  close: number;
  volume: number;
}

export interface Trade {
  entry_time: string;
  entry_price: number;
  exit_time: string;
  exit_price: number;
  profit: string;
  risk_percentage: string;
  isLong: boolean;
  session: string;
  volatility: string;
  stoploss: number;
  rsi: number;
  atr: number;
  supertrend?: number;
  ema8?: number;
  ema13?: number;
  ema200?: number;
  sma13?: number;
  adx?: number;
  isHCandleRanging?: boolean;
  h1_highest?: number;
  h1_lowest?: number;
  losspoint?: number;
  maxpoint?: number;
  stoploss_touched?: boolean;
  partial_exit_price?: number;
  partial_exit_time?: string;
  partial_profit?: string;
  avg_profit?: string;
}

export interface HourStat {
  wins: number;
  losses: number;
  count: number;
}

export interface DayAnalysis {
  profit: string;
  winRate: string;
  count: number;
}

export interface Analysis {
  startTime: string;
  endTime: string;
  totalDays: number;
  totalTrades: number;
  winRate: string;
  totalProfit: string;
  profitFactor: string;
  maxDrawdown: string;
  avgProfit: string;
  avgRisk: string;
  sharpeRatio: string;
  maxWinStreak: number;
  maxLossStreak: number;
  avgRMultiple: string;
  largestDrawdown: string;
  avgDurationWins: string;
  avgDurationLosses: string;
  maxProfitDay: string;
  maxLossDay: string;
  maxProfitMonthly: string;
  maxLossMonthly: string;
  stoplossTouched: number;
  cumulativeProfit: string[];
  sessionProfit: Record<string, number>;
  sessionCounts: Record<string, number>;
  sessionWinRates: Record<string, string>;
  volProfit: Record<string, number>;
  volCounts: Record<string, number>;
  volWinRates: Record<string, string>;
  posProfit: Record<string, number>;
  posCounts: Record<string, number>;
  posWinRates: Record<string, string>;
  bestTrade: Trade;
  worstTrade: Trade;
  hourStats: Record<string, HourStat>;
