              <a href="#" className="hover:text-emerald-500 transition-colors">API Keys</a>
              <a href="#" className="hover:text-emerald-500 transition-colors">Proprietary Research &copy; 2025</a>
           </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

