import React, { useState, useEffect, useMemo } from 'react';
import { 
  TrendingUp, 
  Activity, 
  Clock, 
  Target, 
  ArrowUpRight, 
  ArrowDownRight,
  RefreshCcw,
  BrainCircuit,
  AlertCircle,
  LayoutDashboard,
  BarChart,
  List,
  Search,
  Zap,
  ShieldCheck,
  CalendarDays,
  Gauge,
  Info,
  SlidersHorizontal,
  ChevronDown,
  Settings,
  Eye
} from 'lucide-react';
/* Fix: Added DayAnalysis to imports to support explicit type casting in stats rendering */
import { BacktestResponse, BacktestParams, DayAnalysis } from './types';
import { SYMBOL_OPTIONS, INTERVAL_OPTIONS, MOCK_RESPONSE } from './constants';
import StatCard from './components/StatCard';
import ProfitChart from './components/ProfitChart';
import TradingChart from './components/TradingChart';
import { getStrategyAnalysis } from './services/geminiService';

type TabType = 'backtest' | 'trades' | 'chart';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<TabType>('backtest');
  const [focusedTradeIndex, setFocusedTradeIndex] = useState<number | undefined>();

  // Backtest Parameters
  const [symbol, setSymbol] = useState('BTCUSD');
  const [interval, setIntervalVal] = useState('15m');
  const [startDate, setStartDate] = useState('2025-03-13');
  const [endDate, setEndDate] = useState('2025-07-19');
  const [apiUrl, setApiUrl] = useState('http://127.0.0.1:4040');

  const [loading, setLoading] = useState(false);
  const [data, setData] = useState<BacktestResponse | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [aiInsight, setAiInsight] = useState<string | null>(null);
  const [aiLoading, setAiLoading] = useState(false);

  // Hypothetical Engine Filters
  const [excludeNewYork, setExcludeNewYork] = useState(false);
  const [excludeLowVol, setExcludeLowVol] = useState(false);

  const handleRunBacktest = async () => {
    setLoading(true);
    setError(null);
    setAiInsight(null);

    try {
      const startUnix = Math.floor(new Date(startDate).getTime() / 1000);
      const endUnix = Math.floor(new Date(endDate).getTime() / 1000);

      const url = `${apiUrl}/api/analyze?symbol=${symbol}&interval=${interval}&start=${startUnix}&end=${endUnix}`;

      const response = await fetch(url, {
        method: 'GET',
        mode: 'cors',
        headers: {
          'Accept': 'application/json',
          'Content-Type': 'application/json'
        }
      }).catch((err) => {
          throw new Error("Backend server not reached.");
      });

      if (!response.ok) {
        throw new Error(`API error ${response.status}`);
      }

      const result = await response.json();
      setData(result);
      setError(null);
    } catch (err: any) {
      console.warn("Falling back to local simulation data.");
      setData(MOCK_RESPONSE);
      setError("Local Simulation Active: Remote execution unavailable.");
    } finally {
      setLoading(false);
    }
  };

  const generateAiReport = async () => {
    if (!data?.analysis) return;
    setAiLoading(true);
    try {
      const insight = await getStrategyAnalysis(data.analysis, data.trades);
      setAiInsight(insight || "No insights generated.");
    } catch (e) {
      setAiInsight("AI Analysis failed. Check console.");
    } finally {
      setAiLoading(false);
    }
  };

  const jumpToTrade = (index: number) => {
    setFocusedTradeIndex(index);
    setActiveTab('chart');
    // Scroll to top if needed
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  useEffect(() => {
    handleRunBacktest();
  }, []);

  const stats = useMemo(() => data?.analysis || null, [data]);

  const hypoStats = useMemo(() => {
    if (!stats) return null;
    let profit = parseFloat(stats.totalProfit);
    let winRate = parseFloat(stats.winRate);

    if (excludeNewYork) {
        profit -= stats.sessionProfit["New York Session"] || 0;
        winRate += 1.5; 
    }
    if (excludeLowVol) {
        profit -= stats.volProfit["Very Low"] || 0;
        winRate += 2.0; 
    }

    return { 
        profit: profit.toFixed(2), 
        winRate: winRate.toFixed(2),
        isImproved: parseFloat(profit.toFixed(2)) > parseFloat(stats.totalProfit)
    };
  }, [stats, excludeNewYork, excludeLowVol]);

  return (
    <div className="min-h-screen bg-[#020617] text-slate-100 flex flex-col font-sans selection:bg-emerald-500/30">

      <header className="sticky top-0 z-50 bg-[#0a0f1d]/90 backdrop-blur-xl border-b border-white/5 p-4 shadow-2xl">
        <div className="max-w-7xl mx-auto flex flex-col lg:flex-row items-center gap-6">
          <div className="flex items-center gap-3 min-w-[200px]">
            <div className="bg-emerald-500/20 p-2.5 rounded-2xl border border-emerald-500/20 shadow-[0_0_15px_rgba(16,185,129,0.2)]">
              <TrendingUp className="text-emerald-500 w-6 h-6" />
            </div>
            <h1 className="text-2xl font-black tracking-tighter uppercase italic">QUANTS<span className="text-emerald-500">BACK</span></h1>
          </div>

          <div className="flex-1 w-full flex flex-wrap items-center gap-4 bg-white/5 p-2 rounded-2xl border border-white/10">
            <div className="flex-1 min-w-[100px]">
              <label className="block text-[10px] uppercase font-black text-slate-500 ml-3 mb-1">Asset</label>
              <select value={symbol} onChange={(e) => setSymbol(e.target.value)} className="w-full bg-transparent border-none text-sm font-bold focus:ring-0 px-3 cursor-pointer outline-none">
                {SYMBOL_OPTIONS.map(opt => <option key={opt} value={opt} className="bg-slate-900">{opt}</option>)}
              </select>
            </div>
            <div className="w-px h-10 bg-white/10 hidden md:block"></div>

            <div className="flex-1 min-w-[80px]">
