import React, { useEffect, useRef } from 'react';
import { createChart, IChartApi, ColorType, LineStyle, ISeriesApi } from 'lightweight-charts';
import { Candle, Trade, IndicatorSettings } from '../types';
import { calculateEMA, calculateBollingerBands, calculateRSI, calculateMACD } from '../utils/indicators';

interface TradingChartProps {
  candles: Candle[];
  trades: Trade[];
  focusedTradeId?: number;
  indicatorSettings: IndicatorSettings;
}

const TradingChart: React.FC<TradingChartProps> = ({ candles, trades, focusedTradeId, indicatorSettings }) => {
  const mainChartRef = useRef<HTMLDivElement>(null);
  const rsiChartRef = useRef<HTMLDivElement>(null);
  const macdChartRef = useRef<HTMLDivElement>(null);

  const chartInstances = useRef<{
    main: IChartApi | null;
    rsi: IChartApi | null;
    macd: IChartApi | null;
  }>({ main: null, rsi: null, macd: null });

  const seriesRef = useRef<any>({});

  const parseTime = (dateStr: string) => {
    const [datePart, timePart] = dateStr.split(', ');
    const [day, month, year] = datePart.split('/').map(Number);
    const [hour, min, sec] = timePart.split(':').map(Number);
    return new Date(year, month - 1, day, hour, min, sec).getTime() / 1000;
  };

  useEffect(() => {
    if (!mainChartRef.current || !candles.length) return;

    // --- Main Chart Init ---
    const mainChart = createChart(mainChartRef.current, {
      layout: { background: { type: ColorType.Solid, color: '#0f172a' }, textColor: '#94a3b8' },
      grid: { vertLines: { color: '#1e293b' }, horzLines: { color: '#1e293b' } },
      width: mainChartRef.current.clientWidth,
      height: 450,
      timeScale: { borderColor: '#334155', timeVisible: true, visible: false },
    });
    chartInstances.current.main = mainChart;

    const candleSeries = mainChart.addCandlestickSeries({
      upColor: '#10b981', downColor: '#f43f5e', borderVisible: false,
      wickUpColor: '#10b981', wickDownColor: '#f43f5e',
    });
    seriesRef.current.candles = candleSeries;

    const prices = candles.map(c => c.close);
    const formattedCandles = candles.map(c => ({
      time: c.time as any, open: c.open, high: c.high, low: c.low, close: c.close,
    }));
    candleSeries.setData(formattedCandles);

    // Indicators: EMA
    const emaData = calculateEMA(prices, indicatorSettings.emaPeriod).map((v, i) => ({ time: candles[i].time as any, value: v }));
    const emaSeries = mainChart.addLineSeries({ color: '#3b82f6', lineWidth: 1, title: `EMA ${indicatorSettings.emaPeriod}` });
    emaSeries.setData(emaData);

    // Indicators: BB
    const bbData = calculateBollingerBands(prices, indicatorSettings.bbPeriod, indicatorSettings.bbMultiplier);
    const bbUpper = mainChart.addLineSeries({ color: 'rgba(255, 255, 255, 0.2)', lineWidth: 1, lineStyle: LineStyle.Dashed });
    const bbLower = mainChart.addLineSeries({ color: 'rgba(255, 255, 255, 0.2)', lineWidth: 1, lineStyle: LineStyle.Dashed });
    bbUpper.setData(bbData.map((v, i) => ({ time: candles[i].time as any, value: v.upper || 0 })).filter(d => d.value !== 0));
    bbLower.setData(bbData.map((v, i) => ({ time: candles[i].time as any, value: v.lower || 0 })).filter(d => d.value !== 0));

    // --- RSI Chart Init ---
    if (rsiChartRef.current) {
      const rsiChart = createChart(rsiChartRef.current, {
        layout: { background: { type: ColorType.Solid, color: '#0f172a' }, textColor: '#94a3b8' },
        width: rsiChartRef.current.clientWidth, height: 120,
        grid: { vertLines: { visible: false }, horzLines: { color: '#1e293b' } },
        timeScale: { visible: false },
      });
      chartInstances.current.rsi = rsiChart;
      const rsiSeries = rsiChart.addLineSeries({ color: '#f59e0b', lineWidth: 2, title: `RSI ${indicatorSettings.rsiPeriod}` });
      const rsiVal = calculateRSI(prices, indicatorSettings.rsiPeriod);
      rsiSeries.setData(rsiVal.map((v, i) => ({ time: candles[i].time as any, value: v })).filter(d => d.value !== null));

      // RSI Levels
      const rsi70 = rsiChart.addLineSeries({ color: 'rgba(244, 63, 94, 0.3)', lineWidth: 1, lineStyle: LineStyle.Dotted });
      const rsi30 = rsiChart.addLineSeries({ color: 'rgba(16, 185, 129, 0.3)', lineWidth: 1, lineStyle: LineStyle.Dotted });
      rsi70.setData(candles.map(c => ({ time: c.time as any, value: 70 })));
      rsi30.setData(candles.map(c => ({ time: c.time as any, value: 30 })));
    }

    // --- MACD Chart Init ---
    if (macdChartRef.current) {
      const macdChart = createChart(macdChartRef.current, {
        layout: { background: { type: ColorType.Solid, color: '#0f172a' }, textColor: '#94a3b8' },
        width: macdChartRef.current.clientWidth, height: 150,
        grid: { vertLines: { visible: false }, horzLines: { color: '#1e293b' } },
        timeScale: { borderColor: '#334155', timeVisible: true },
      });
      chartInstances.current.macd = macdChart;
      const { macdLine, signalLine, histogram } = calculateMACD(
        prices, 
        indicatorSettings.macdFast, 
        indicatorSettings.macdSlow, 
        indicatorSettings.macdSignal
      );

      const mLine = macdChart.addLineSeries({ color: '#3b82f6', lineWidth: 1.5 });
      const sLine = macdChart.addLineSeries({ color: '#f59e0b', lineWidth: 1.5 });
      const hGram = macdChart.addHistogramSeries({ color: '#475569' });

      mLine.setData(macdLine.map((v, i) => ({ time: candles[i].time as any, value: v })));
      sLine.setData(signalLine.map((v, i) => ({ time: candles[i].time as any, value: v })));
      hGram.setData(histogram.map((v, i) => ({ 
        time: candles[i].time as any, 
        value: v, 
        color: v >= 0 ? 'rgba(16, 185, 129, 0.5)' : 'rgba(244, 63, 94, 0.5)' 
      })));
    }

    // Markers
    const markers: any[] = [];
    trades.forEach((trade) => {
      const isWin = parseFloat(trade.profit) >= 0;
      const entryT = parseTime(trade.entry_time);
      const exitT = parseTime(trade.exit_time);

      markers.push({
        time: entryT,
        position: trade.isLong ? 'belowBar' : 'aboveBar',
        color: trade.isLong ? '#10b981' : '#f43f5e',
        shape: trade.isLong ? 'arrowUp' : 'arrowDown',
        text: `Entry`,
      });

      markers.push({
        time: exitT,
        position: isWin ? 'aboveBar' : 'belowBar',
        color: isWin ? '#fbbf24' : '#64748b',
        shape: 'circle',
        text: `Exit`,
      });
    });
    candleSeries.setMarkers(markers);

    // Sync Time Scales
    const sync = (source: IChartApi, targets: IChartApi[]) => {
      source.timeScale().subscribeVisibleTimeRangeChange((range) => {
        targets.forEach(t => t.timeScale().setVisibleRange(range as any));
      });
    };

    if (chartInstances.current.main && chartInstances.current.rsi && chartInstances.current.macd) {
      sync(chartInstances.current.main, [chartInstances.current.rsi, chartInstances.current.macd]);
      sync(chartInstances.current.rsi, [chartInstances.current.main, chartInstances.current.macd]);
      sync(chartInstances.current.macd, [chartInstances.current.main, chartInstances.current.rsi]);
    }

    const handleResize = () => {
      const w = mainChartRef.current?.clientWidth || 0;
      mainChart.applyOptions({ width: w });
      chartInstances.current.rsi?.applyOptions({ width: w });
      chartInstances.current.macd?.applyOptions({ width: w });
    };
    window.addEventListener('resize', handleResize);

    return () => {
      window.removeEventListener('resize', handleResize);
      mainChart.remove();
      chartInstances.current.rsi?.remove();
      chartInstances.current.macd?.remove();
    };
  }, [candles, trades, indicatorSettings]);

  useEffect(() => {
    if (!chartInstances.current.main || !seriesRef.current.candles) return;

    if (focusedTradeId !== undefined && trades[focusedTradeId]) {
      const trade = trades[focusedTradeId];
      const entryTime = parseTime(trade.entry_time);
      const exitTime = parseTime(trade.exit_time);

      // Focus view
      const padding = 3600 * 6; // 6 hours
      chartInstances.current.main.timeScale().setVisibleRange({
        from: (entryTime - padding) as any,
        to: (exitTime + padding) as any,
      });

      // Price lines for focused trade
      if (seriesRef.current.slLine) seriesRef.current.candles.removePriceLine(seriesRef.current.slLine);
      if (seriesRef.current.entryLine) seriesRef.current.candles.removePriceLine(seriesRef.current.entryLine);
      if (seriesRef.current.exitLine) seriesRef.current.candles.removePriceLine(seriesRef.current.exitLine);

      seriesRef.current.slLine = seriesRef.current.candles.createPriceLine({
        price: trade.stoploss, color: '#f43f5e', lineWidth: 2, lineStyle: LineStyle.Dashed, axisLabelVisible: true, title: 'SL',
      });
      seriesRef.current.entryLine = seriesRef.current.candles.createPriceLine({
        price: trade.entry_price, color: '#94a3b8', lineWidth: 2, lineStyle: LineStyle.Solid, axisLabelVisible: true, title: 'Entry',
      });
      seriesRef.current.exitLine = seriesRef.current.candles.createPriceLine({
        price: trade.exit_price, color: '#fbbf24', lineWidth: 2, lineStyle: LineStyle.Dotted, axisLabelVisible: true, title: 'Exit',
      });
    }
  }, [focusedTradeId, trades]);

  return (
    <div className="flex flex-col gap-2 w-full bg-slate-900 border border-slate-800 rounded-xl p-2 relative shadow-2xl overflow-hidden">
      <div className="absolute top-4 left-6 z-10 flex items-center gap-4 bg-slate-900/90 border border-slate-700/50 p-2 px-3 rounded-lg backdrop-blur">
         <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Multi-Indicator Analytics Engine</span>
      </div>
      <div ref={mainChartRef} className="w-full" />
      <div ref={rsiChartRef} className="w-full border-t border-slate-800/50" />
      <div ref={macdChartRef} className="w-full border-t border-slate-800/50" />
    </div>
  );
};

