interface StatCardProps {
  label: string;
  value: string | number;
  subValue?: string;
  trend?: 'up' | 'down' | 'neutral';
  prefix?: string;
  suffix?: string;
  labelColor?: string;
  variant?: 'green' | 'dark' | 'purple' | 'red' | 'orange' | 'teal' | 'brown' | 'pink';
  icon?: React.ReactNode;
}

const StatCard: React.FC<StatCardProps> = ({ label, value, subValue, trend, prefix, suffix, variant, icon }) => {
  const getVariantStyles = () => {
    switch (variant) {
      case 'green': return 'bg-emerald-600 border-emerald-500 text-white';
      case 'dark': return 'bg-[#1e293b] border-[#334155] text-white';
      case 'purple': return 'bg-purple-700 border-purple-600 text-white';
      case 'red': return 'bg-rose-700 border-rose-600 text-white';
      case 'orange': return 'bg-amber-600 border-amber-500 text-white';
      case 'teal': return 'bg-teal-700 border-teal-600 text-white';
      case 'brown': return 'bg-[#78350f] border-[#92400e] text-white';
      case 'pink': return 'bg-pink-700 border-pink-600 text-white';
      default: return 'bg-slate-800/50 border-slate-700 text-slate-100';
    }
  };

  return (
    <div className={`${getVariantStyles()} border p-5 rounded-xl shadow-lg transition-transform hover:scale-[1.02] flex flex-col items-center justify-center text-center relative overflow-hidden`}>
