      </ResponsiveContainer>
    </div>
  );
};

// --- Daily Profit Heatmap ---
export const DailyProfitHeatmap: React.FC<{ data: Record<string, number> }> = ({ data }) => {
  const days = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
  // Simplified heatmap: Map dates to color intensity
  const getColor = (val: number) => {
    if (val > 1.5) return '#22c55e'; // Deep green
    if (val > 0.5) return '#4ade80'; // Med green
    if (val > 0) return '#86efac';   // Light green
    if (val < -1.5) return '#ef4444'; // Deep red
    if (val < -0.5) return '#f87171'; // Med red
    if (val < 0) return '#fca5a5';   // Light red
    return '#334155'; // No trade
  };

  const today = new Date();
  const weeks = [];
  for (let i = 0; i < 52; i++) {
    const week = [];
    for (let j = 0; j < 7; j++) {
      const date = new Date(today);
      date.setDate(today.getDate() - (51 - i) * 7 - (6 - j));
      const dateStr = date.toISOString().split('T')[0];
      week.push({ date: dateStr, value: data[dateStr] || 0 });
    }
    weeks.push(week);
  }

  return (
    <div className="bg-[#1e293b]/50 border border-white/5 p-6 rounded-2xl overflow-hidden">
      <h3 className="text-sm font-black text-slate-100 mb-6 uppercase tracking-widest">Daily Profit Heatmap</h3>
      <div className="flex gap-1 overflow-x-auto pb-4 custom-scrollbar">
        <div className="flex flex-col gap-1 pt-6 pr-2">
          {days.map(d => <span key={d} className="text-[8px] text-slate-500 font-bold uppercase h-[12px]">{d}</span>)}
        </div>
        {weeks.map((week, wi) => (
          <div key={wi} className="flex flex-col gap-1">
            {week.map((day, di) => (
              <div 
                key={di} 
                title={`${day.date}: ${day.value.toFixed(2)}%`}
                className="w-3 h-3 rounded-sm transition-transform hover:scale-125" 
                style={{ backgroundColor: getColor(day.value) }} 
              />
            ))}
          </div>
        ))}
      </div>
      <div className="flex items-center justify-center gap-4 mt-4 text-[8px] font-black text-slate-500 uppercase">
        <span>Loss</span>
        <div className="flex gap-1">
          <div className="w-2 h-2 rounded-sm bg-[#ef4444]"></div>
          <div className="w-2 h-2 rounded-sm bg-[#f87171]"></div>
          <div className="w-2 h-2 rounded-sm bg-[#fca5a5]"></div>
          <div className="w-2 h-2 rounded-sm bg-[#334155]"></div>
          <div className="w-2 h-2 rounded-sm bg-[#86efac]"></div>
          <div className="w-2 h-2 rounded-sm bg-[#4ade80]"></div>
          <div className="w-2 h-2 rounded-sm bg-[#22c55e]"></div>
        </div>
        <span>Profit</span>
      </div>
    </div>
  );
};

