  data: Record<string, any>; 
  dataKey: string; 
  color: string;
  yLabel?: string;
}> = ({ title, data, dataKey, color, yLabel }) => {
  // Fix: Explicitly cast entries and use String() wrapper to ensure parseFloat receives a string
  const chartData = (Object.entries(data) as [string, any][]).map(([name, value]) => ({
    name,
    val: (typeof value === 'object' && value !== null) 
      ? parseFloat(String(value[dataKey])) 
      : parseFloat(String(value)),
  }));

