// --- Daily Profit Heatmap ---
export const DailyProfitHeatmap: React.FC<{ data: Record<string, number> }> = ({ data }) => {
  const days = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
  const months = ['Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec', 'Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun'];

  const getColor = (val: number) => {
    if (val > 1.0) return '#22c55e';
    if (val > 0.3) return '#4ade80';
    if (val > 0) return '#86efac';
    if (val < -1.0) return '#ef4444';
    if (val < -0.3) return '#f87171';
    if (val < 0) return '#fca5a5';
    return '#1e293b'; // No trade
  };

  const today = new Date();
  const weeksCount = 52;
  const weeks = [];

  for (let i = 0; i < weeksCount; i++) {
    const week = [];
    for (let j = 0; j < 7; j++) {
      const date = new Date(today);
      // Calculate date based on weeks from today
      date.setDate(today.getDate() - (weeksCount - 1 - i) * 7 - (6 - j));
      const dateStr = date.toISOString().split('T')[0];
      week.push({ date: dateStr, value: data[dateStr] || 0, dayIndex: j, month: date.getMonth() });
    }
    weeks.push(week);
  }

  return (
    <div className="bg-[#0f172a] border border-white/5 p-6 rounded-xl">
      <h3 className="text-sm font-black text-slate-100 mb-6 uppercase tracking-widest">Daily Profit Heatmap</h3>
      <div className="flex gap-2">
        <div className="flex flex-col gap-1.5 pt-6">
          {days.map((d, i) => (
            <span key={d} className={`text-[8px] font-bold uppercase h-3 flex items-center ${i % 2 === 0 ? 'text-slate-500' : 'text-transparent'}`}>{d}</span>
          ))}
        </div>
        <div className="flex-1 overflow-x-auto custom-scrollbar pb-4">
          <div className="flex gap-1.5 min-w-max">
            {weeks.map((week, wi) => (
              <div key={wi} className="flex flex-col gap-1.5">
                {/* Simplified month markers */}
                <div className="h-4 text-[8px] font-bold text-slate-600 uppercase">
                  {wi % 4 === 0 && months[week[0].month]}
                </div>
                {week.map((day, di) => (
                  <div 
                    key={di} 
                    title={`${day.date}: ${day.value.toFixed(2)}%`}
                    className="w-3 h-3 rounded-sm transition-all hover:scale-150 cursor-pointer relative group"
                    style={{ backgroundColor: getColor(day.value) }} 
                  >
                     <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 hidden group-hover:block z-50 pointer-events-none">
                        <div className="bg-slate-900 border border-slate-700 text-[8px] font-black whitespace-nowrap px-2 py-1 rounded shadow-xl uppercase">
                           {day.date}: <span className={day.value >= 0 ? 'text-emerald-400' : 'text-rose-400'}>{day.value.toFixed(2)}%</span>
                        </div>
                     </div>
                  </div>
                ))}
              </div>
            ))}
          </div>
        </div>
      </div>
      <div className="flex items-center justify-end gap-3 mt-4 text-[8px] font-black text-slate-500 uppercase">
        <span>Less Profit</span>
        <div className="flex gap-1">
          <div className="w-2.5 h-2.5 rounded-sm bg-[#ef4444]"></div>
          <div className="w-2.5 h-2.5 rounded-sm bg-[#f87171]"></div>
          <div className="w-2.5 h-2.5 rounded-sm bg-[#fca5a5]"></div>
          <div className="w-2.5 h-2.5 rounded-sm bg-[#1e293b]"></div>
          <div className="w-2.5 h-2.5 rounded-sm bg-[#86efac]"></div>
          <div className="w-2.5 h-2.5 rounded-sm bg-[#4ade80]"></div>
          <div className="w-2.5 h-2.5 rounded-sm bg-[#22c55e]"></div>
        </div>
        <span>More Profit</span>
      </div>
    </div>
  );
};

