import React, { useState, useEffect, useMemo } from 'react';
import { 
  TrendingUp, Activity, Clock, Target, ArrowUpRight, ArrowDownRight, RefreshCcw, 
  BrainCircuit, LayoutDashboard, BarChart, List, Zap, ShieldCheck, 
  Settings, Eye, DollarSign, Percent, Scale, TrendingDown, Layers, MousePointer2, Briefcase, Gem,
  ZapOff, Award, AlertTriangle, Calendar, ChevronRight, PlayCircle, Info
} from 'lucide-react';
import { BacktestResponse, DayAnalysis, IndicatorSettings, Trade } from './types';
import { ASSET_OPTIONS, INTERVAL_OPTIONS, STRATEGY_OPTIONS, MOCK_RESPONSE } from './constants';
import StatCard from './components/StatCard';
import ProfitChart from './components/ProfitChart';
import TradingChart from './components/TradingChart';
import { 
  HourlyTradingStats, 
  DailyProfitHeatmap, 
  SimplePerformanceBar, 
  PositionPieChart 
} from './components/DashboardCharts';
import { getStrategyAnalysis } from './services/geminiService';

type TabType = 'backtest' | 'trades' | 'chart';
type AppView = 'config' | 'dashboard';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('config');
  const [activeTab, setActiveTab] = useState<TabType>('backtest');
  const [focusedTradeIndex, setFocusedTradeIndex] = useState<number | undefined>();

  // Backtest Parameters
  const [strategy, setStrategy] = useState(STRATEGY_OPTIONS[0].id);
  const [symbol, setSymbol] = useState('BTCUSD');
  const [interval, setIntervalVal] = useState('15m');
  const [startDate, setStartDate] = useState('2025-03-13');
  const [startTime, setStartTime] = useState('00:00');
  const [endDate, setEndDate] = useState('2025-07-19');
  const [endTime, setEndTime] = useState('23:59');
  const [apiUrl, setApiUrl] = useState('http://127.0.0.1:4040');

  const [indicatorSettings, setIndicatorSettings] = useState<IndicatorSettings>({
    emaPeriod: 20, bbPeriod: 20, bbMultiplier: 2, rsiPeriod: 14, macdFast: 12, macdSlow: 26, macdSignal: 9
  });

  const [loading, setLoading] = useState(false);
  const [data, setData] = useState<BacktestResponse | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [aiInsight, setAiInsight] = useState<string | null>(null);
  const [aiLoading, setAiLoading] = useState(false);

  const handleRunBacktest = async () => {
    setLoading(true);
    setError(null);
    setAiInsight(null);

    try {
      const startDateTime = new Date(`${startDate}T${startTime}`);
      const endDateTime = new Date(`${endDate}T${endTime}`);
      const startUnix = Math.floor(startDateTime.getTime() / 1000);
      const endUnix = Math.floor(endDateTime.getTime() / 1000);

      const url = `${apiUrl}/api/analyze?symbol=${symbol}&interval=${interval}&start=${startUnix}&end=${endUnix}&strategy=${strategy}`;

      const response = await fetch(url, {
        method: 'GET',
        mode: 'cors',
        headers: { 'Accept': 'application/json', 'Content-Type': 'application/json' }
      });

      if (!response.ok) throw new Error(`API error ${response.status}`);
      const result = await response.json();
      setData(result);
      setView('dashboard');
    } catch (err: any) {
      console.warn("Falling back to local simulation data.");
      setData(MOCK_RESPONSE);
      setView('dashboard');
      setError("Local Simulation Active: Remote execution unavailable.");
    } finally {
      setLoading(false);
    }
  };

  const generateAiReport = async () => {
    if (!data?.analysis) return;
    setAiLoading(true);
    try {
      const insight = await getStrategyAnalysis(data.analysis, data.trades);
      setAiInsight(insight || "No insights generated.");
    } catch (e) {
      setAiInsight("AI Analysis failed. Check console.");
    } finally {
      setAiLoading(false);
    }
  };

  const jumpToTrade = (index: number) => {
    setFocusedTradeIndex(index);
    setActiveTab('chart');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const stats = useMemo(() => data?.analysis || null, [data]);

  const TradeInfoCard = ({ trade, title, type }: { trade: Trade, title: string, type: 'best' | 'worst' }) => (
