      <h3 className="text-sm font-black text-slate-100 mb-6 uppercase tracking-[0.2em] flex items-center gap-2">
        {type === 'best' ? <Award className="w-4 h-4 text-emerald-400" /> : <AlertTriangle className="w-4 h-4 text-rose-400" />}
        {title}
      </h3>
      <div className="space-y-4 flex-1">
        <div className="flex justify-between items-center border-b border-white/5 pb-3">
          <span className="text-[10px] font-black text-slate-500 uppercase">Profit</span>
          <span className={`text-xl font-black tracking-tighter ${parseFloat(trade.profit) >= 0 ? 'text-emerald-400' : 'text-rose-400'}`}>
            {parseFloat(trade.profit) > 0 ? '$' : '-$'}{Math.abs(parseFloat(trade.profit) * 100).toFixed(2)}
          </span>
        </div>
        <div className="grid grid-cols-2 gap-4">
          <div className="space-y-1">
            <span className="text-[8px] font-black text-slate-600 uppercase">Entry Time</span>
            <p className="text-[10px] font-bold text-slate-300">{trade.entry_time}</p>
          </div>
          <div className="space-y-1">
            <span className="text-[8px] font-black text-slate-600 uppercase">Session</span>
            <p className="text-[10px] font-bold text-slate-300">{trade.session}</p>
          </div>
          <div className="space-y-1">
            <span className="text-[8px] font-black text-slate-600 uppercase">Volatility</span>
            <p className="text-[10px] font-bold text-slate-300">{trade.volatility}</p>
          </div>
          <div className="space-y-1">
            <span className="text-[8px] font-black text-slate-600 uppercase">Direction</span>
            <p className="text-[10px] font-bold text-slate-300 uppercase">{trade.isLong ? 'Long' : 'Short'}</p>
          </div>
        </div>
      </div>
      <button 
        onClick={() => {
           const idx = data?.trades.findIndex(t => t.entry_time === trade.entry_time);
           if (idx !== undefined && idx !== -1) jumpToTrade(idx);
        }}
        className="mt-6 w-full py-2.5 bg-slate-800 hover:bg-slate-700 text-white rounded-lg text-[10px] font-black uppercase tracking-widest transition-all"
      >
        Track on Chart
      </button>
    </div>
  );

  if (view === 'config') {
    return (
      <div className="min-h-screen bg-[#020617] text-slate-100 font-sans p-6 md:p-12 flex flex-col items-center">
        <div className="max-w-4xl w-full space-y-12">
          <div className="flex flex-col items-center text-center space-y-4">
            <div className="bg-emerald-500/20 p-4 rounded-3xl border border-emerald-500/20 shadow-[0_0_30px_rgba(16,185,129,0.1)] mb-4">
              <TrendingUp className="text-emerald-500 w-10 h-10" />
            </div>
            <h1 className="text-4xl font-black tracking-tighter uppercase italic">QUANTS<span className="text-emerald-500">BACK</span></h1>
            <p className="text-slate-500 text-sm font-bold uppercase tracking-[0.3em]">Institutional Grade Strategy Laboratory</p>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
