              <h2 className="text-xs font-black uppercase tracking-[0.4em] text-slate-400 flex items-center gap-2">
                <PlayCircle className="w-4 h-4" /> 01. Select Strategy
              </h2>
              <div className="grid grid-cols-1 gap-4">
                {STRATEGY_OPTIONS.map((opt) => (
                  <button
                    key={opt.id}
                    onClick={() => setStrategy(opt.id)}
                    className={`text-left p-6 rounded-2xl border transition-all duration-300 relative overflow-hidden group ${
                      strategy === opt.id 
                        ? 'bg-emerald-500/10 border-emerald-500 shadow-[0_0_20px_rgba(16,185,129,0.1)]' 
                        : 'bg-white/5 border-white/10 hover:border-white/20'
                    }`}
                  >
                    <div className="flex items-center gap-4 relative z-10">
                      <div className={`p-3 rounded-xl ${strategy === opt.id ? 'bg-emerald-500 text-white' : 'bg-white/5 text-slate-400'}`}>
                        {opt.icon === 'Zap' ? <Zap className="w-5 h-5" /> : <Activity className="w-5 h-5" />}
                      </div>
                      <div>
                        <h3 className="font-black text-sm uppercase tracking-widest mb-1">{opt.name}</h3>
                        <p className="text-[10px] text-slate-500 font-medium leading-relaxed">{opt.description}</p>
                      </div>
                    </div>
                  </button>
                ))}
              </div>
            </div>

            <div className="space-y-6">
              <h2 className="text-xs font-black uppercase tracking-[0.4em] text-slate-400 flex items-center gap-2">
                <Target className="w-4 h-4" /> 02. Parameters
              </h2>
              <div className="bg-white/5 border border-white/10 rounded-3xl p-8 space-y-6 shadow-2xl">
                <div className="grid grid-cols-2 gap-6">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase text-slate-500 tracking-widest">Asset</label>
                    <select value={symbol} onChange={(e) => setSymbol(e.target.value)} className="w-full bg-slate-900 border border-white/10 rounded-xl p-3 text-xs font-bold text-white outline-none focus:border-emerald-500 transition-all cursor-pointer">
