                   </div>
                   <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <div className="space-y-2">
                        <label className="text-[8px] font-black text-slate-600 uppercase">From</label>
                        <div className="flex gap-2">
                          <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="flex-1 bg-slate-900 border border-white/10 rounded-xl p-3 text-[10px] font-bold text-white outline-none" />
                          <input type="time" value={startTime} onChange={(e) => setStartTime(e.target.value)} className="w-24 bg-slate-900 border border-white/10 rounded-xl p-3 text-[10px] font-bold text-white outline-none" />
                        </div>
                      </div>
                      <div className="space-y-2">
                        <label className="text-[8px] font-black text-slate-600 uppercase">To</label>
                        <div className="flex gap-2">
                          <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="flex-1 bg-slate-900 border border-white/10 rounded-xl p-3 text-[10px] font-bold text-white outline-none" />
                          <input type="time" value={endTime} onChange={(e) => setEndTime(e.target.value)} className="w-24 bg-slate-900 border border-white/10 rounded-xl p-3 text-[10px] font-bold text-white outline-none" />
                        </div>
                      </div>
                   </div>
                </div>

                <button 
                  onClick={handleRunBacktest}
                  disabled={loading}
                  className="w-full bg-emerald-500 hover:bg-emerald-600 text-white py-4 rounded-2xl text-sm font-black uppercase tracking-[0.2em] transition-all shadow-[0_10px_30px_rgba(16,185,129,0.3)] disabled:opacity-50 flex items-center justify-center gap-3 active:scale-[0.98]"
                >
                  {loading ? <RefreshCcw className="w-5 h-5 animate-spin" /> : <Zap className="w-5 h-5" />}
                  {loading ? 'Initializing Simulation...' : 'Execute Backtest'}
                </button>
              </div>
            </div>
          </div>

          <div className="pt-12 border-t border-white/5 flex flex-col md:flex-row justify-between items-center gap-8 opacity-40">
             <div className="flex items-center gap-3">
               <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
               <span className="text-[9px] font-black uppercase tracking-widest text-slate-400">Server Status: Online & Latency Optimized</span>
             </div>
             <div className="flex gap-6">
