type TabType = 'backtest' | 'trades' | 'chart';
type AppView = 'config' | 'dashboard';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('config');
  const [activeTab, setActiveTab] = useState<TabType>('backtest');
  const [focusedTradeIndex, setFocusedTradeIndex] = useState<number | undefined>();

  // Backtest Parameters
  const [strategy, setStrategy] = useState(STRATEGY_OPTIONS[0].id);
  const [symbol, setSymbol] = useState('BTCUSD');
  const [interval, setIntervalVal] = useState('15m');
  const [startDateTime, setStartDateTime] = useState('2025-03-13T00:00');
  const [endDateTime, setEndDateTime] = useState('2025-07-19T23:59');
  const [apiUrl, setApiUrl] = useState('http://127.0.0.1:4040');

  const [indicatorSettings, setIndicatorSettings] = useState<IndicatorSettings>({
    indicators: [
      { id: 'ema-1', type: 'EMA', visible: true, color: '#3b82f6', params: { period: 20 } },
      { id: 'rsi-1', type: 'RSI', visible: true, color: '#f59e0b', params: { period: 14 } },
      { id: 'bb-1', type: 'BB', visible: true, color: '#ffffff', params: { period: 20, multiplier: 2.5 } }
    ]
  });

  const [loading, setLoading] = useState(false);
  const [data, setData] = useState<BacktestResponse | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [aiInsight, setAiInsight] = useState<string | null>(null);
  const [aiLoading, setAiLoading] = useState(false);

  const handleRunBacktest = async () => {
    setLoading(true);
    setError(null);
    setAiInsight(null);

    try {
      const startUnix = Math.floor(new Date(startDateTime).getTime() / 1000);
      const endUnix = Math.floor(new Date(endDateTime).getTime() / 1000);

      const url = `${apiUrl}/api/analyze?symbol=${symbol}&interval=${interval}&start=${startUnix}&end=${endUnix}&strategy=${strategy}`;

      const response = await fetch(url, {
        method: 'GET',
        mode: 'cors',
        headers: { 'Accept': 'application/json', 'Content-Type': 'application/json' }
      });

      if (!response.ok) throw new Error(`API error ${response.status}`);
      const result = await response.json();
      setData(result);
      setView('dashboard');
    } catch (err: any) {
      console.warn("Falling back to local simulation data.");
      setData(MOCK_RESPONSE);
      setView('dashboard');
      setError("Local Simulation Active: Remote execution unavailable.");
    } finally {
      setLoading(false);
    }
  };

  const jumpToTrade = (index: number) => {
    setFocusedTradeIndex(index);
    setActiveTab('chart');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const stats = useMemo(() => data?.analysis || null, [data]);

  const removeIndicator = (id: string) => {
    setIndicatorSettings(prev => ({
      indicators: prev.indicators.filter(i => i.id !== id)
    }));
  };

  const addIndicator = (type: IndicatorConfig['type']) => {
    const id = `${type.toLowerCase()}-${Date.now()}`;
    const colors: Record<string, string> = { EMA: '#3b82f6', BB: '#ffffff', RSI: '#f59e0b', MACD: '#8b5cf6' };
    const params: Record<string, any> = {
      EMA: { period: 20 },
      BB: { period: 20, multiplier: 2 },
      RSI: { period: 14 },
      MACD: { fast: 12, slow: 26, signal: 9 }
    };
    const newIndicator: IndicatorConfig = {
      id,
      type,
      visible: true,
      color: colors[type],
      params: params[type]
    };
    setIndicatorSettings(prev => ({ indicators: [...prev.indicators, newIndicator] }));
  };

  const updateIndicator = (id: string, updates: Partial<IndicatorConfig>) => {
    setIndicatorSettings(prev => ({
      indicators: prev.indicators.map(i => i.id === id ? { ...i, ...updates } : i)
    }));
  };

  const updateParam = (id: string, paramKey: string, val: number) => {
    setIndicatorSettings(prev => ({
      indicators: prev.indicators.map(i => i.id === id ? { ...i, params: { ...i.params, [paramKey]: val } } : i)
    }));
  };

  const generateAiReport = async () => {
    if (!data?.analysis) return;
    setAiLoading(true);
    try {
      const insight = await getStrategyAnalysis(data.analysis, data.trades);
      setAiInsight(insight || "No insights generated.");
    } catch (e) {
      setAiInsight("AI Analysis failed. Check console.");
    } finally {
      setAiLoading(false);
    }
  };

  if (view === 'config') {
    return (
      <div className="min-h-screen bg-[#020617] text-slate-100 font-sans p-6 md:p-12 flex flex-col items-center justify-center">
        <div className="max-w-4xl w-full space-y-10">
          <div className="text-center space-y-4">
            <div className="inline-block bg-emerald-500/10 p-5 rounded-3xl border border-emerald-500/20 shadow-2xl mb-2">
              <TrendingUp className="text-emerald-500 w-12 h-12" />
            </div>
            <h1 className="text-5xl font-black tracking-tighter uppercase italic">QUANTS<span className="text-emerald-500">BACK</span></h1>
            <p className="text-slate-500 font-bold uppercase tracking-[0.4em] text-sm">Synthetic Intelligence Trading Suite</p>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-8 items-stretch">
            <div className="bg-white/[0.02] border border-white/5 p-8 rounded-[2.5rem] space-y-8 flex flex-col">
              <h2 className="text-xs font-black uppercase tracking-[0.4em] text-emerald-500 flex items-center gap-3">
                <PlayCircle className="w-5 h-5" /> Selection Engine
              </h2>
